UNITS_10 = ["", "një", "dy", "tre", "katër", "pesë", "gjashtë", "shtatë", "tetë", "nëntë"]
TENS = {1: "dhjetë", 2: "njëzet", 3: "tridhjetë", 4: "dyzet", 5: "pesëdhjetë", 6: "gjashtëdhjetë", 7: "shtatëdhjetë", 8: "tetëdhjetë", 9: "nëntëdhjetë"}
def number(n):
    if n == 100: return "njëqind"
    if n < 10: return UNITS_10[n] if n else "zero"
    if n == 10: return "dhjetë"
    if n < 20: return UNITS_10[n - 10] + "mbëdhjetë"
    t, u = divmod(n, 10)
    return TENS[t] + ("" if not u else " e " + UNITS_10[u])
NUMBERS = [(n, number(n)) for n in range(0, 101)]
